import SwiftUI
import AppKit

public struct MinistroLogoView: View {
    private static let base64Image = ""
    
    private static let cachedImage: NSImage? = {
        guard let data = Data(base64Encoded: base64Image),
              let img = NSImage(data: data) else {
            return nil
        }
        img.isTemplate = false
        return img
    }()

    public init() {}

    public var body: some View {
        if let nsImage = Self.cachedImage {
            Image(nsImage: nsImage)
                .renderingMode(.original)
                .resizable()
                .scaledToFit()
                .frame(maxWidth: .infinity, maxHeight: 22, alignment: .center)
        } else {
            Text("MINISTRO DEVELOPER")
                .font(.system(size: 11, weight: .bold))
                .foregroundStyle(.primary)
                .frame(maxWidth: .infinity, alignment: .center)
        }
    }
}
